-- One-off for the live database of PeroniaMU (2026-10-15): rebuilds the monster spots of Devias
-- from its original spawns, which had been changed by hand before the update "Group Monsters Into Spots".
-- Backup: D:\OpenMU-backups\db\antes-devias-spots-2026-10-15.dump
BEGIN;
DO $$
DECLARE deleted int;
BEGIN
  DELETE FROM config."MonsterSpawnArea" s
  USING config."MonsterDefinition" d
  WHERE s."MonsterDefinitionId" = d."Id"
    AND s."GameMapId" = '00000300-0002-0000-0000-000000000000'
    AND s."Id"::text LIKE '00000602-0002-4e%'
    AND d."Number" BETWEEN 20 AND 25
    AND s."SpawnTrigger" = 0;
  GET DIAGNOSTICS deleted = ROW_COUNT;
  IF deleted <> 12 THEN RAISE EXCEPTION 'expected 12 spots of Devias, found %', deleted; END IF;
END $$;
DO $$
DECLARE spots int; hotspots int;
BEGIN
  SELECT count(*), count(*) FILTER (WHERE "Quantity" = 7) INTO spots, hotspots
  FROM config."MonsterSpawnArea"
  WHERE "GameMapId" = '00000300-0002-0000-0000-000000000000' AND "Id"::text LIKE '00000602-0002-4e%';
  IF spots <> 131 OR hotspots <> 28 THEN RAISE EXCEPTION 'expected 131 spots and 28 hotspots, found % and %', spots, hotspots; END IF;
END $$;
COMMIT;
